1	export const dynamic = "force-dynamic";
2	
3	import { requireUser } from "@/lib/auth";
4	import { db } from "@/lib/db";
5	import { SupportView } from "@/components/nx/SupportView";
6	import { getHelpData } from "@/lib/help";
7	import { getHealth, overallStatus, uptimeSummary, listIncidents, HEALTH_COMPONENTS } from "@/lib/monitoring";
8	import { COMPONENT_LABELS } from "@/lib/status-copy";
9	
10	/* Support, on the concept's structure — Tickets / Live Chat / Help Center /
11	 * Service Status.
12	 *
13	 * The concept's stat strip also carries "99.8% Customer Satisfaction" — that
14	 * one has no backing data anywhere in this platform (no CSAT survey exists),
15	 * so it stays out. Its neighbour, "Avg response time", DOES now have a real
16	 * source: the gap between a ticket's own `createdAt` (the opening message)
17	 * and the first staff reply is a real, measured duration, not a marketing
18	 * SLA — so it is computed below from this customer's own ticket history
19	 * instead of being either fabricated or dropped. `null` ("not enough data
20	 * yet") when none of their tickets have a staff reply yet.
21	 *
22	 * What else IS measured: how many of your tickets are open, how many are
23	 * waiting on you, and how many closed recently (TicketStatus); the real Help
24	 * Center content (lib/help.ts, grouped published BlogPosts — the same data
25	 * /help runs on); and the real platform health/incident history
26	 * (lib/monitoring.ts — the same data the public /status page runs on).
27	 */
28	export default async function SupportPage({
29	  searchParams,
30	}: {
31	  searchParams: Promise<{ ticket?: string }>;
32	}) {
33	  const user = await requireUser();
34	  const { ticket: initialTicketId } = await searchParams;
35	  const monthAgo = new Date(Date.now() - 30 * 86_400_000);
36	
37	  const [tickets, closedRecently, firstStaffReplies, helpData, health, uptime, incidents] = await Promise.all([
38	    db.ticket.findMany({
39	      where: { userId: user.id },
40	      select: {
41	        id: true, subject: true, status: true, priority: true,
42	        createdAt: true, updatedAt: true,
43	        messages: {
44	          select: { body: true, isStaff: true, createdAt: true },
45	          orderBy: { createdAt: "desc" },
46	          take: 1,
47	        },
48	      },
49	      orderBy: { updatedAt: "desc" },
50	      take: 40,
51	    }),
52	    db.ticket.count({
53	      where: { userId: user.id, status: "CLOSED", updatedAt: { gte: monthAgo } },
54	    }),
55	    db.ticketMessage.groupBy({
56	      by: ["ticketId"],
57	      where: { ticket: { userId: user.id }, isStaff: true },
58	      _min: { createdAt: true },
59	    }),
60	    getHelpData(),
61	    getHealth(),
62	    uptimeSummary(),
63	    listIncidents(),
64	  ]);
65	
66	  const rows = tickets.map((t) => ({
67	    id: t.id,
68	    subject: t.subject,
69	    status: t.status,
70	    priority: t.priority,
71	    updated: t.updatedAt.toISOString(),
72	    /* The last message, trimmed for the list. Staff or customer is marked so a
73	       reader can tell at a glance whose move it is. */
74	    preview: t.messages[0]?.body.replace(/\s+/g, " ").slice(0, 120) ?? "",
75	    lastFromStaff: t.messages[0]?.isStaff ?? false,
76	  }));
77	
78	  const firstReplyByTicket = new Map(firstStaffReplies.map((r) => [r.ticketId, r._min.createdAt]));
79	  const responseMinutes: number[] = [];
80	  for (const t of tickets) {
81	    const firstStaffAt = firstReplyByTicket.get(t.id);
82	    if (firstStaffAt) responseMinutes.push((firstStaffAt.getTime() - t.createdAt.getTime()) / 60000);
83	  }
84	  const avgResponseMin = responseMinutes.length > 0
85	    ? Math.round(responseMinutes.reduce((a, b) => a + b, 0) / responseMinutes.length)
86	    : null;
87	
88	  const help = helpData.sections.map((s) => ({
89	    name: s.category.name,
90	    slug: s.category.slug,
91	    emoji: s.category.emoji,
92	    blurb: s.category.blurb,
93	    count: s.posts.length,
94	  }));
95	
96	  /* Combine open + resolved into one recent-incidents list, newest first,
97	     capped small — this is a support tab, not the full status page. */
98	  const recentIncidents = [...incidents.open, ...incidents.resolved]
99	    .sort((a, b) => new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime())
100	    .slice(0, 6);
101	
102	  return (
103	    <SupportView
104	      viewer={{ name: user.name ?? null, email: user.email ?? null }}
105	      viewerId={user.id}
106	      tickets={rows}
107	      open={rows.filter((t) => t.status !== "CLOSED").length}
108	      /* "Waiting for you" is ANSWERED — staff replied and the ball is in the
109	         customer's court. That is the state worth surfacing; it is the one they
110	         can act on. */
111	      waitingOnYou={rows.filter((t) => t.status === "ANSWERED").length}
112	      closedRecently={closedRecently}
113	      avgResponseMin={avgResponseMin}
114	      initialTicketId={initialTicketId ?? null}
115	      help={help}
116	      helpTotal={helpData.total}
117	      status={{
118	        overall: overallStatus(health),
119	        components: HEALTH_COMPONENTS.map((key) => ({
120	          key,
121	          label: COMPONENT_LABELS[key],
122	          status: health[key].status,
123	          uptimePct: uptime[key].pct,
124	        })),
125	        incidents: recentIncidents.map((inc) => ({
126	          id: inc.id,
127	          title: inc.title,
128	          body: inc.body,
129	          severity: inc.severity,
130	          startedAt: inc.startedAt,
131	          resolvedAt: inc.resolvedAt,
132	        })),
133	      }}
134	    />
135	  );
136	}
