1	export const dynamic = "force-dynamic";
2	
3	import { impersonating, requireUser } from "@/lib/auth";
4	import { db } from "@/lib/db";
5	import { hasChargeableCard, listPaymentCards } from "@/lib/stripe-cards";
6	import { readBwMeterHealth, bwUsageView } from "@/lib/bandwidth";
7	import { BillingView } from "@/components/nx/BillingView";
8	
9	/* Billing, on the concept's structure.
10	 *
11	 * EVERY FIGURE IS COMPUTED FROM RECORDS, not estimated. The six-month chart is
12	 * a GROUP BY over paid invoices; "next charge" is the earliest real expiry
13	 * across the things that actually renew; "active services" counts them; the
14	 * month-over-month percentage is last calendar month's real paid total, not a
15	 * guess; the usage tab's bytes come straight from the same meter the worker
16	 * writes (`lib/bandwidth.ts`), including its "not measured yet" state — never
17	 * a synthesized 0%.
18	 *
19	 * The concept's "Your Plan — Nexion Pro, $24.99/mo" card is deliberately NOT
20	 * here. Nxeon has no account-level subscription — it sells per service — so
21	 * that card would describe a product that does not exist. The active-services
22	 * figure says the true version of the same thing.
23	 */
24	export default async function BillingPage() {
25	  const user = await requireUser();
26	  const now = new Date();
27	  const sixMonthsAgo = new Date(now.getFullYear(), now.getMonth() - 5, 1);
28	  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
29	  const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
30	
31	  const [invoices, paidSince, monthInvoices, lastMonthInvoices, servers, hosting, domains, bwServers, suspendedUnpaid] = await Promise.all([
32	    db.invoice.findMany({
33	      where: { userId: user.id },
34	      select: {
35	        id: true, number: true, amountCents: true, taxCents: true, status: true,
36	        description: true, paidAt: true, periodStart: true, refundedCents: true,
37	      },
38	      orderBy: { number: "desc" },
39	      take: 60,
40	    }),
41	    db.invoice.findMany({
42	      where: { userId: user.id, status: "PAID", paidAt: { gte: sixMonthsAgo } },
43	      select: { amountCents: true, taxCents: true, paidAt: true },
44	    }),
45	    db.invoice.aggregate({
46	      where: { userId: user.id, status: "PAID", paidAt: { gte: monthStart } },
47	      _sum: { amountCents: true, taxCents: true },
48	    }),
49	    db.invoice.aggregate({
50	      where: { userId: user.id, status: "PAID", paidAt: { gte: lastMonthStart, lt: monthStart } },
51	      _sum: { amountCents: true, taxCents: true },
52	    }),
53	    db.server.findMany({
54	      where: { userId: user.id, status: { notIn: ["DELETING"] } },
55	      select: { hostname: true, expiresAt: true, autoRenew: true },
56	    }),
57	    db.hostingAccount.findMany({
58	      where: { userId: user.id, status: { in: ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] } },
59	      select: { primaryDomain: true, expiresAt: true },
60	    }),
61	    db.domain.findMany({
62	      where: { userId: user.id, status: "ACTIVE" },
63	      select: { name: true, expiresAt: true },
64	    }),
65	    db.server.findMany({
66	      where: { userId: user.id, status: { not: "DELETING" } },
67	      select: { hostname: true, status: true, bwInBytes: true, bwOutBytes: true, bwWindowStart: true, plan: { select: { bandwidthTB: true } } },
68	      orderBy: { createdAt: "asc" },
69	    }),
70	    // Same predicate app/dashboard/servers/[id]/page.tsx already uses for
71	    // `suspendedUnpaid` — a server suspended specifically for non-payment (as
72	    // opposed to abuse, ToS, etc), which is exactly what `settleOutstanding`
73	    // can clear with a card. Not gated on `isFree`/`expiresAt` here: a server
74	    // that reached this suspended-for-non-payment state already has both.
75	    db.server.findMany({
76	      where: { userId: user.id, status: "SUSPENDED", suspendedNote: { contains: "unpaid" } },
77	      select: { id: true, hostname: true },
78	    }),
79	  ]);
80	
81	  /* Six calendar months, oldest first, zero-filled. A month with no spend is a
82	     zero bar rather than a gap — a chart that silently drops empty months
83	     misrepresents the shape of the spend. */
84	  const buckets: { label: string; cents: number }[] = [];
85	  for (let i = 5; i >= 0; i--) {
86	    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
87	    buckets.push({ label: d.toLocaleDateString(undefined, { month: "short" }), cents: 0 });
88	  }
89	  for (const inv of paidSince) {
90	    if (!inv.paidAt) continue;
91	    const idx = (inv.paidAt.getFullYear() - now.getFullYear()) * 12 + (inv.paidAt.getMonth() - now.getMonth()) + 5;
92	    if (idx >= 0 && idx < 6) buckets[idx].cents += inv.amountCents + inv.taxCents;
93	  }
94	
95	  const monthCents = (monthInvoices._sum.amountCents ?? 0) + (monthInvoices._sum.taxCents ?? 0);
96	  const lastMonthCents = (lastMonthInvoices._sum.amountCents ?? 0) + (lastMonthInvoices._sum.taxCents ?? 0);
97	  // Withheld rather than shown as 0%/∞% when there is nothing real to compare
98	  // against — a made-up percentage is worse than none.
99	  const monthPct = lastMonthCents > 0 ? Math.round(((monthCents - lastMonthCents) / lastMonthCents) * 100) : null;
100	
101	  // An admin impersonating a customer must not be able to attach, remove or
102	  // use a card on their account (lib/actions-payment-method.ts refuses these
103	  // server-side) — the controls are hidden rather than left to throw on click.
104	  const isImpersonating = (await impersonating()) !== null;
105	
106	  const renewables = [
107	    ...servers.map((s) => ({ name: s.hostname, kind: "Server", at: s.expiresAt, auto: s.autoRenew })),
108	    ...hosting.map((h) => ({ name: h.primaryDomain, kind: "Hosting", at: h.expiresAt, auto: true })),
109	    ...domains.map((d) => ({ name: d.name, kind: "Domain", at: d.expiresAt, auto: true })),
110	  ].filter((r) => r.at) as { name: string; kind: string; at: Date; auto: boolean }[];
111	  renewables.sort((a, b) => a.at.getTime() - b.at.getTime());
112	  const next = renewables[0] ?? null;
113	  const daysUntilNext = next ? Math.max(0, Math.round((next.at.getTime() - now.getTime()) / 86_400_000)) : null;
114	
115	  // Same meter the worker sweeps and the same "measured" gate the original
116	  // dashboard's Usage panel uses — a server this has never metered reports
117	  // that honestly instead of a fabricated 0%.
118	  const cards = await listPaymentCards(user.id);
119	
120	  const bwHealth = await readBwMeterHealth();
121	  const bandwidth = bwServers.map((s) => {
122	    const view = bwUsageView(s, (s.plan?.bandwidthTB ?? 0) * 1e12, bwHealth);
123	    return {
124	      hostname: s.hostname,
125	      measured: view.measured,
126	      usedBytes: view.usedBytes,
127	      allowanceBytes: view.allowanceBytes,
128	      pct: view.pct,
129	      partial: view.partial,
130	    };
131	  });
132	
133	  return (
134	    <BillingView
135	      balanceCents={user.balanceCents}
136	      totalSixMonthCents={buckets.reduce((n, b) => n + b.cents, 0)}
137	      monthCents={monthCents}
138	      monthPct={monthPct}
139	      buckets={buckets}
140	      activeServices={servers.length + hosting.length + domains.length}
141	      next={next ? { name: next.name, kind: next.kind, at: next.at.toISOString() } : null}
142	      daysUntilNext={daysUntilNext}
143	      /* The summary line, which is one entry per KIND of method — not the full
144	         card list. The account's PRIMARY card is the one mirrored onto `User`
145	         (brand/last4/expiry cached for display), and there is at most one
146	         vaulted PayPal (`paypalVaultId`). Every saved card, including the
147	         non-primary ones, rides the `cards` prop below from
148	         `listPaymentCards` — a customer may have several. */
149	      methods={[
150	        ...(hasChargeableCard(user) && user.cardLast4 ? [{
151	          kind: "card" as const,
152	          label: user.cardBrand ?? "Card",
153	          detail: `•••• ${user.cardLast4}`,
154	          expires: user.cardExpMonth && user.cardExpYear
155	            ? `${String(user.cardExpMonth).padStart(2, "0")}/${user.cardExpYear}` : null,
156	        }] : []),
157	        ...(user.paypalVaultId ? [{
158	          kind: "paypal" as const,
159	          label: "PayPal",
160	          detail: user.paypalPayerEmail ?? "Vaulted account",
161	          expires: null,
162	        }] : []),
163	      ]}
164	      invoices={invoices.map((i) => ({
165	        id: i.id, number: i.number,
166	        cents: i.amountCents + i.taxCents,
167	        refundedCents: i.refundedCents,
168	        status: i.status,
169	        description: i.description ?? "",
170	        at: (i.paidAt ?? i.periodStart)?.toISOString() ?? null,
171	      }))}
172	      cardOnFile={hasChargeableCard(user)}
173	      isImpersonating={isImpersonating}
174	      autoRecharge={{
175	        enabled: user.autoRechargeEnabled,
176	        thresholdCents: user.autoRechargeThresholdCents,
177	        amountCents: user.autoRechargeAmountCents,
178	      }}
179	      bandwidth={bandwidth}
180	      cards={cards}
181	      outstanding={suspendedUnpaid.map((s) => ({ serverId: s.id, hostname: s.hostname }))}
182	    />
183	  );
184	}
185

1	import { db } from "./db";
2	import { pve, node as primaryNode, pveFor } from "./proxmox";
3	import type { Node } from "@prisma/client";
4	import { COMPONENT_LABELS, SEVERITY_LABEL, type HealthComponentKey } from "./status-copy";
5	import { alertIncidentOpened, alertIncidentResolved } from "./discord-status-alerts";
6	
7	/**
8	 * Shared, READ-ONLY monitoring helpers for Nxeon.
9	 *
10	 * Everything here is safe to call from server components (status page, admin
11	 * monitoring) and from the worker sweep (`worker/monitor.ts`). No mutations,
12	 * no secrets in the returned shapes — the public /status page renders off the
13	 * same `getHealth()` logic the API exposes.
14	 *
15	 * Proxmox access is strictly read-only: `GET /nodes/{node}/status` and
16	 * `GET /nodes/{node}/storage/{storage}/status` (+ backup content listing).
17	 */
18	
19	export type CompStatus = "operational" | "degraded" | "down";
20	export type Component = { status: CompStatus; detail: string };
21	
22	export type HealthReport = {
23	  web: Component;
24	  db: Component;
25	  worker: Component;
26	  proxmox: Component;
27	  checkedAt: string;
28	};
29	
30	// ---- Thresholds (env-overridable) ---------------------------------------
31	
32	/** Worker is expected to touch the queue within this window; older QUEUED work ⇒ down. */
33	export const WORKER_STALE_MS = Number(process.env.NXEON_WORKER_STALE_MS ?? 2 * 60_000);
34	/** A Job sitting in RUNNING longer than this is considered stuck. */
35	export const STUCK_JOB_MS = Number(process.env.NXEON_STUCK_JOB_MS ?? 15 * 60_000);
36	/** Storage usage above this fraction trips a disk-capacity alert. */
37	export const DISK_WARN_RATIO = Number(process.env.NXEON_DISK_WARN_RATIO ?? 0.85);
38	/** Node RAM usage above this fraction trips an alert. */
39	export const RAM_WARN_RATIO = Number(process.env.NXEON_RAM_WARN_RATIO ?? 0.9);
40	/** No fresh backup within this window ⇒ backups look stale. */
41	export const BACKUP_STALE_MS = Number(process.env.NXEON_BACKUP_STALE_MS ?? 48 * 60 * 60_000);
42	/** QUEUED backlog at/above this depth trips an alert. */
43	export const QUEUE_BACKLOG_ALERT = Number(process.env.NXEON_QUEUE_BACKLOG_ALERT ?? 25);
44	
45	// ---- Small formatters ----------------------------------------------------
46	
47	/** Compact human age from a millisecond duration. */
48	export function fmtAge(ms: number): string {
49	  if (ms < 0) ms = 0;
50	  const m = Math.floor(ms / 60_000);
51	  if (m < 1) return "just now";
52	  if (m < 60) return `${m}m`;
53	  const h = Math.floor(m / 60);
54	  if (h < 24) return `${h}h`;
55	  const d = Math.floor(h / 24);
56	  return `${d}d ${h % 24}h`;
57	}
58	
59	// ---- Proxmox targets (read-only) ----------------------------------------
60	
61	type PveTarget = {
62	  label: string;
63	  pveNode: string;
64	  get: (path: string, params?: Record<string, any>) => Promise<any>;
65	  /** Distinct storages worth watching on this node. */
66	  storages: string[];
67	};
68	
69	/**
70	 * Resolve the set of Proxmox nodes to poll. Prefers explicit `Node` rows
71	 * (multi-node), and falls back to the env-configured primary when none exist.
72	 */
73	export async function nodeTargets(): Promise<PveTarget[]> {
74	  const nodes = await db.node.findMany({
75	    where: { enabled: true },
76	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
77	  });
78	  if (nodes.length === 0) {
79	    return [
80	      {
81	        label: primaryNode || "primary",
82	        pveNode: primaryNode,
83	        get: (p, pp) => pve.get(p, pp),
84	        storages: ["vmdata", "backup"],
85	      },
86	    ];
87	  }
88	  return nodes.map((n: Node) => {
89	    const client = pveFor({
90	      apiUrl: n.apiUrl,
91	      pveNode: n.pveNode,
92	      tokenId: n.tokenId,
93	      tokenSecret: n.tokenSecret,
94	    });
95	    const storages = [n.storageNvme, n.storageHdd, "backup"].filter(
96	      (v, i, a) => v && a.indexOf(v) === i
97	    );
98	    return { label: n.name, pveNode: n.pveNode, get: client.get, storages };
99	  });
100	}
101	
102	export type StorageUsage = {
103	  node: string;
104	  storage: string;
105	  total: number;
106	  used: number;
107	  avail: number;
108	  ratio: number;
109	  reachable: boolean;
110	};
111	
112	/** Per-node, per-storage disk usage (bytes). Unreachable storages are marked. */
113	export async function nodeStorageUsage(): Promise<StorageUsage[]> {
114	  const targets = await nodeTargets();
115	  const out: StorageUsage[] = [];
116	  for (const t of targets) {
117	    for (const storage of t.storages) {
118	      try {
119	        const st = await t.get(`/nodes/${t.pveNode}/storage/${storage}/status`);
120	        const total = Number(st?.total ?? 0);
121	        const used = Number(st?.used ?? 0);
122	        const avail = Number(st?.avail ?? Math.max(0, total - used));
123	        out.push({
124	          node: t.label,
125	          storage,
126	          total,
127	          used,
128	          avail,
129	          ratio: total > 0 ? used / total : 0,
130	          reachable: true,
131	        });
132	      } catch {
133	        out.push({ node: t.label, storage, total: 0, used: 0, avail: 0, ratio: 0, reachable: false });
134	      }
135	    }
136	  }
137	  return out;
138	}
139	
140	export type NodeRam = {
141	  node: string;
142	  total: number;
143	  used: number;
144	  ratio: number;
145	  cpu: number;
146	  /** Physical CPU thread count reported by the node (cpuinfo.cpus). 0 if unknown. */
147	  cores: number;
148	  reachable: boolean;
149	};
150	
151	/** Per-node RAM + CPU load from the node status endpoint. */
152	export async function nodeRamUsage(): Promise<NodeRam[]> {
153	  const targets = await nodeTargets();
154	  return Promise.all(
155	    targets.map(async (t) => {
156	      try {
157	        const s = await t.get(`/nodes/${t.pveNode}/status`);
158	        const total = Number(s?.memory?.total ?? 0);
159	        const used = Number(s?.memory?.used ?? 0);
160	        return {
161	          node: t.label,
162	          total,
163	          used,
164	          ratio: total > 0 ? used / total : 0,
165	          cpu: Number(s?.cpu ?? 0),
166	          // Proxmox reports the host's thread count under cpuinfo.cpus; used only
167	          // as the denominator for vCPU-overcommit context in lib/node-capacity.
168	          cores: Number(s?.cpuinfo?.cpus ?? 0),
169	          reachable: true,
170	        };
171	      } catch {
172	        return { node: t.label, total: 0, used: 0, ratio: 0, cpu: 0, cores: 0, reachable: false };
173	      }
174	    })
175	  );
176	}
177	
178	export type BackupSummary = {
179	  node: string;
180	  count: number;
181	  /** Unix seconds of the most recent backup (freshness signal). */
182	  newestCtime: number | null;
183	  /** Unix seconds of the oldest backup on disk. */
184	  oldestCtime: number | null;
185	  reachable: boolean;
186	};
187	
188	/**
189	 * Summarise backups PER NODE (never merged — a healthy node must not mask a
190	 * silently-broken one). Tries every storage `nodeTargets()` already lists for
191	 * that node (not a hardcoded "backup") since the vzdump-archive storage name
192	 * isn't uniform across nodes — the primary's happens to be literally named
193	 * `backup`; node-2's is `vmdata-hdd`. Best-effort per storage: one that isn't
194	 * backup-content-capable on a given node is simply skipped, not fatal.
195	 */
196	export async function backupSummary(): Promise<BackupSummary[]> {
197	  const targets = await nodeTargets();
198	  return Promise.all(
199	    targets.map(async (t) => {
200	      let count = 0;
201	      let newest: number | null = null;
202	      let oldest: number | null = null;
203	      let reachable = false;
204	      for (const storage of t.storages) {
205	        try {
206	          const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/${storage}/content`, {
207	            content: "backup",
208	          });
209	          reachable = true;
210	          for (const b of items ?? []) {
211	            const ct = Number(b?.ctime ?? 0);
212	            if (!ct) continue;
213	            count++;
214	            if (newest === null || ct > newest) newest = ct;
215	            if (oldest === null || ct < oldest) oldest = ct;
216	          }
217	        } catch {
218	          // this storage isn't backup-content-capable on this node — try the next
219	        }
220	      }
221	      return { node: t.label, count, newestCtime: newest, oldestCtime: oldest, reachable };
222	    })
223	  );
224	}
