271	/**
272	 * Worker liveness inferred from the Job queue:
273	 *  - QUEUED work older than WORKER_STALE_MS that hasn't been picked up ⇒ down
274	 *    (the loop isn't draining the queue).
275	 *  - Jobs stuck RUNNING past STUCK_JOB_MS ⇒ degraded.
276	 *  - Otherwise operational (an empty/fresh queue is healthy, even if idle).
277	 */
278	export async function workerHealth(): Promise<WorkerHealth> {
279	  const now = Date.now();
280	  const [newest, stuckRunning, queuedBacklog, staleQueued] = await Promise.all([
281	    db.job.findFirst({ orderBy: { updatedAt: "desc" }, select: { updatedAt: true } }),
282	    db.job.count({ where: { status: "RUNNING", updatedAt: { lt: new Date(now - STUCK_JOB_MS) } } }),
283	    db.job.count({ where: { status: "QUEUED" } }),
284	    db.job.count({ where: { status: "QUEUED", createdAt: { lt: new Date(now - WORKER_STALE_MS) } } }),
285	  ]);
286	
287	  let status: CompStatus = "operational";
288	  let detail = newest
289	    ? `last job update ${fmtAge(now - newest.updatedAt.getTime())} ago`
290	    : "idle — no jobs processed yet";
291	
292	  if (staleQueued > 0) {
293	    status = "down";
294	    detail = `${staleQueued} job(s) queued but not picked up — worker may be stopped`;
295	  } else if (stuckRunning > 0) {
296	    status = "degraded";
297	    detail = `${stuckRunning} job(s) stuck running > ${Math.round(STUCK_JOB_MS / 60_000)}m`;
298	  }
299	
300	  return {
301	    status,
302	    detail,
303	    newestUpdatedAt: newest?.updatedAt ?? null,
304	    stuckRunning,
305	    queuedBacklog,
306	    staleQueued,
307	  };
308	}
