373	/** Consecutive unhealthy samples before an incident auto-opens. */
374	export const INCIDENT_OPEN_STREAK = Number(process.env.NXEON_INCIDENT_OPEN_STREAK ?? 3);
375	/** Consecutive healthy samples before an auto-incident auto-resolves. */
376	export const INCIDENT_RESOLVE_STREAK = Number(process.env.NXEON_INCIDENT_RESOLVE_STREAK ?? 2);
377	/** HealthSample rows older than this are pruned each sweep (keeps the 90-day window backed). */
378	export const HEALTH_SAMPLE_RETENTION_DAYS = Number(process.env.NXEON_HEALTH_RETENTION_DAYS ?? 95);
379	/** Default uptime / timeline window. */
380	export const UPTIME_WINDOW_MS = Number(process.env.NXEON_UPTIME_WINDOW_MS ?? 90 * 24 * 60 * 60_000);
381	
382	/** Worst-of over a set of statuses (down > degraded > operational). */
383	export function worstStatus(statuses: CompStatus[]): CompStatus {
384	  if (statuses.includes("down")) return "down";
385	  if (statuses.includes("degraded")) return "degraded";
386	  return "operational";
387	}
