389	// ---- Pure math (no DB, injected clock) ----------------------------------
390	
391	/** Minimal shape the pure readers work on — a status stamped at a time. */
392	export type SampleLite = { status: CompStatus; ts: Date | string | number };
393	
394	function tsMs(t: Date | string | number): number {
395	  return t instanceof Date ? t.getTime() : new Date(t).getTime();
396	}
397	
398	export type UptimeResult = {
399	  /** Fraction operational over the window, 0..100. `null` = no samples yet ("collecting data"). */
400	  pct: number | null;
401	  total: number;
402	  up: number;
403	  degraded: number;
404	  down: number;
405	};
406	
407	/**
408	 * Uptime % from samples in `[now - windowMs, now]`. Only `operational` counts as
409	 * up — degraded/down are both downtime. Returns `pct: null` when the window has
410	 * NO samples, so callers say "collecting data" instead of fabricating 100%.
411	 */
412	export function uptimeFromSamples(samples: SampleLite[], now: number, windowMs: number): UptimeResult {
413	  const cutoff = now - windowMs;
414	  let total = 0;
415	  let up = 0;
416	  let degraded = 0;
417	  let down = 0;
418	  for (const s of samples) {
419	    const t = tsMs(s.ts);
420	    if (t < cutoff || t > now) continue;
421	    total++;
422	    if (s.status === "operational") up++;
423	    else if (s.status === "degraded") degraded++;
424	    else down++;
425	  }
426	  return { pct: total === 0 ? null : (up / total) * 100, total, up, degraded, down };
427	}
428	
429	export type TimelineBucket = {
430	  start: number;
431	  end: number;
432	  /** Worst status observed in the bucket, or `null` when no samples landed in it. */
433	  status: CompStatus | null;
434	  total: number;
435	};
436	
437	/**
438	 * Split the window into `bucketCount` equal buckets and reduce each to its WORST
439	 * status (a single degraded reading in a day colours that day amber). Empty
440	 * buckets stay `null` — the strip renders them as "no data", never as green.
441	 */
442	export function bucketTimeline(
443	  samples: SampleLite[],
444	  now: number,
445	  windowMs: number,
446	  bucketCount: number
447	): TimelineBucket[] {
448	  const n = Math.max(1, Math.floor(bucketCount));
449	  const bucketMs = windowMs / n;
450	  const start0 = now - windowMs;
451	  const buckets: TimelineBucket[] = Array.from({ length: n }, (_, i) => ({
452	    start: start0 + i * bucketMs,
453	    end: start0 + (i + 1) * bucketMs,
454	    status: null,
455	    total: 0,
456	  }));
457	  for (const s of samples) {
458	    const t = tsMs(s.ts);
459	    if (t < start0 || t > now) continue;
460	    let idx = Math.floor((t - start0) / bucketMs);
461	    if (idx < 0) idx = 0;
462	    if (idx >= n) idx = n - 1;
463	    const b = buckets[idx];
464	    b.total++;
465	    b.status = b.status === null ? s.status : worstStatus([b.status, s.status]);
466	  }
467	  return buckets;
468	}
