470	export type IncidentDecision =
471	  | { action: "open"; severity: "degraded" | "down" }
472	  | { action: "resolve" }
473	  | { action: "none" };
474	
475	/**
476	 * The auto-incident state machine, pure and deterministic.
477	 *
478	 * `recent` is the most-recent-first run of a component's sample statuses (newest
479	 * at index 0). With no open incident, a leading run of >= INCIDENT_OPEN_STREAK
480	 * unhealthy samples opens one (severity = down if the newest is down, else
481	 * degraded). With one open, a leading run of >= INCIDENT_RESOLVE_STREAK healthy
482	 * samples resolves it. Anything else is a no-op — this is called every sweep, so
483	 * it must be idempotent once the streak condition is (un)met.
484	 */
485	export function decideIncident(recent: CompStatus[], hasOpenIncident: boolean): IncidentDecision {
486	  if (recent.length === 0) return { action: "none" };
487	
488	  let unhealthyStreak = 0;
489	  for (const s of recent) {
490	    if (s !== "operational") unhealthyStreak++;
491	    else break;
492	  }
493	  let healthyStreak = 0;
494	  for (const s of recent) {
495	    if (s === "operational") healthyStreak++;
496	    else break;
497	  }
498	
499	  if (!hasOpenIncident) {
500	    if (unhealthyStreak >= INCIDENT_OPEN_STREAK) {
501	      return { action: "open", severity: recent[0] === "down" ? "down" : "degraded" };
502	    }
503	    return { action: "none" };
504	  }
505	  if (healthyStreak >= INCIDENT_RESOLVE_STREAK) return { action: "resolve" };
506	  return { action: "none" };
507	}
