509	/**
510	 * Public-safe copy for an auto-opened incident. Deliberately generic — it names
511	 * the friendly component and the severity, and never embeds the probe's raw
512	 * `detail` (which can carry host:port / upstream error text).
513	 */
514	export function autoIncidentCopy(
515	  component: HealthComponent,
516	  severity: "degraded" | "down"
517	): { title: string; body: string } {
518	  const name = COMPONENT_LABELS[component] ?? component;
519	  const what = severity === "down" ? "a service disruption" : "degraded performance";
520	  return {
521	    title: `${name}: ${SEVERITY_LABEL[severity]}`,
522	    body:
523	      `Our automated monitoring detected ${what} affecting ${name}. Engineers have been ` +
524	      `notified and this incident will update automatically as the component recovers.`,
525	  };
526	}
