529	
530	/**
531	 * Persist one HealthSample per component AND advance the auto-incident state
532	 * machine. Called on the worker monitor cadence (see worker/monitor.ts →
533	 * sampleHealthSweep). Cheap and idempotent: 4-row insert, one small read + at
534	 * most one write per component, plus a bounded retention prune.
535	 */
536	export async function sampleHealth(now: Date = new Date()): Promise<void> {
537	  const report = await getHealth();
538	
539	  await db.healthSample.createMany({
540	    data: HEALTH_COMPONENTS.map((c) => ({
541	      component: c,
542	      status: report[c].status,
543	      detail: report[c].detail ? report[c].detail.slice(0, 240) : null,
544	      ts: now,
545	    })),
546	  });
547	
548	  const lookback = Math.max(INCIDENT_OPEN_STREAK, INCIDENT_RESOLVE_STREAK, 1);
549	  for (const c of HEALTH_COMPONENTS) {
550	    const recentRows = await db.healthSample.findMany({
551	      where: { component: c },
552	      orderBy: { ts: "desc" },
553	      take: lookback,
554	      select: { status: true },
555	    });
556	    const recent = recentRows.map((r) => r.status as CompStatus);
557	    const open = await db.statusIncident.findFirst({
558	      where: { component: c, resolvedAt: null, auto: true },
559	      orderBy: { startedAt: "desc" },
560	    });
561	    const decision = decideIncident(recent, !!open);
562	    if (decision.action === "open" && !open) {
563	      const copy = autoIncidentCopy(c, decision.severity);
564	      const incident = await db.statusIncident.create({
565	        data: { component: c, severity: decision.severity, title: copy.title, body: copy.body, auto: true, startedAt: now },
566	      });
567	      await alertIncidentOpened(incident);
568	    } else if (decision.action === "resolve" && open) {
569	      await db.statusIncident.update({ where: { id: open.id }, data: { resolvedAt: now } });
570	      await alertIncidentResolved(open);
571	    }
572	  }
573	
574	  // Retention prune — best-effort, never blocks a sample.
575	  try {
576	    const cutoff = new Date(now.getTime() - HEALTH_SAMPLE_RETENTION_DAYS * 24 * 60 * 60_000);
577	    await db.healthSample.deleteMany({ where: { ts: { lt: cutoff } } });
578	  } catch (e) {
579	    console.error("[monitor] health-sample prune error", e);
580	  }
581	}
