718	/** Queue depth + settled job outcomes over the window, straight from the Job table. */
719	export async function jobStats(
720	  windowMs = 24 * 60 * 60_000,
721	  now: number = Date.now()
722	): Promise<JobStats> {
723	  const since = new Date(now - windowMs);
724	  const [done, failed, queued, running] = await Promise.all([
725	    db.job.count({ where: { status: "DONE", updatedAt: { gte: since } } }),
726	    db.job.count({ where: { status: "FAILED", updatedAt: { gte: since } } }),
727	    db.job.count({ where: { status: "QUEUED" } }),
728	    db.job.count({ where: { status: "RUNNING" } }),
729	  ]);
730	  const settled = done + failed;
731	  return { windowMs, done, failed, queued, running, failureRate: settled === 0 ? null : failed / settled };
732	}
