27	 * fallback (see `categoryMeta`), so the KB never drops content.
28	 */
29	const CATEGORY_META: Omit<HelpCategory, "slug">[] = [
30	  { name: "Gaming", emoji: "🎮", blurb: "Minecraft, Rust, and other game-server setup and tuning." },
31	  { name: "VPS", emoji: "🖥️", blurb: "Provisioning, managing, and getting the most from your VPS." },
