35	  { name: "Domains", emoji: "🌐", blurb: "Registering, pointing, and managing your domain names." },
36	  { name: "Hosting", emoji: "☁️", blurb: "Choosing and running the right hosting for your project." },
37	  { name: "Guides", emoji: "📗", blurb: "Practical, no-fluff guides for people who self-host." },
38	  { name: "Comparisons", emoji: "⚖️", blurb: "Head-to-head breakdowns to help you decide." },
39	];
40	
41	const META_BY_NAME = new Map(CATEGORY_META.map((c) => [c.name.toLowerCase(), c]));
42	
43	/** Turn a category name into a stable, URL-safe slug for the ?c= filter. */
44	export function categorySlug(name: string): string {
45	  return name
46	    .toLowerCase()
47	    .trim()
48	    .replace(/[^a-z0-9]+/g, "-")
49	    .replace(/^-+|-+$/g, "");
50	}
51	
52	/** Metadata for a category, falling back gracefully for unknown categories. */
53	export function categoryMeta(name: string): HelpCategory {
54	  const known = META_BY_NAME.get(name.toLowerCase());
55	  if (known) return { ...known, slug: categorySlug(known.name) };
56	  return { name, slug: categorySlug(name), emoji: "📄", blurb: `Articles about ${name}.` };
57	}
58	
59	export type HelpSection = {
60	  category: HelpCategory;
61	  posts: BlogPost[];
62	};
63	
64	export type HelpData = {
65	  /** All published posts, newest first. */
66	  all: BlogPost[];
67	  /** Posts grouped into KB sections, sections ordered by CATEGORY_META then A–Z. */
68	  sections: HelpSection[];
69	  /** A small hand-off set of the newest articles for the "popular" rail. */
70	  popular: BlogPost[];
71	  /** Total number of published articles. */
72	  total: number;
73	};
74	
75	/**
76	 * Load every published post and shape it into the help-center view model:
77	 * grouped sections, a "popular" rail, and totals. One DB round-trip.
78	 */
79	export async function getHelpData(): Promise<HelpData> {
80	  const all = await getPublishedPosts();
81	
82	  const buckets = new Map<string, BlogPost[]>();
83	  for (const post of all) {
84	    const key = post.category || "Guides";
85	    const list = buckets.get(key);
86	    if (list) list.push(post);
87	    else buckets.set(key, [post]);
88	  }
89	
90	  // Order: curated categories first (in CATEGORY_META order), then any extras A–Z.
91	  const order = new Map(CATEGORY_META.map((c, i) => [c.name.toLowerCase(), i]));
92	  const sections: HelpSection[] = [...buckets.entries()]
93	    .map(([name, posts]) => ({ category: categoryMeta(name), posts }))
94	    .sort((a, b) => {
95	      const ai = order.has(a.category.name.toLowerCase()) ? order.get(a.category.name.toLowerCase())! : 999;
96	      const bi = order.has(b.category.name.toLowerCase()) ? order.get(b.category.name.toLowerCase())! : 999;
97	      if (ai !== bi) return ai - bi;
98	      return a.category.name.localeCompare(b.category.name);
99	    });
100	
101	  return {
102	    all,
103	    sections,
104	    popular: all.slice(0, 6),
105	    total: all.length,
106	  };
107	}
