const [tickets, closedRecently, firstStaffReplies, helpData, health, uptime, incidents] = await Promise.all([
  db.ticket.findMany({
    where: { userId: user.id },
    select: {
      id: true, subject: true, status: true, priority: true,
      createdAt: true, updatedAt: true,
    },
    orderBy: { updatedAt: "desc" },
    take: 40,
  }),
  db.ticket.count({
    where: { userId: user.id, status: "CLOSED", updatedAt: { gte: monthAgo } },
  }),
  db.ticketMessage.groupBy({
    by: ["ticketId"],
    where: { ticket: { userId: user.id }, isStaff: true },
    _min: { createdAt: true },
  }),
  getHelpData(),
  getHealth(),
  uptimeSummary(),
  listIncidents(),
]);

/* The latest message per ticket, for the list preview. This used to ride
   along as a nested `messages: { orderBy, take: 1 }` select on the ticket
   query above — but Prisma's default ("query") relation strategy has no
   SQL-level LIMIT per parent for a nested to-many `take`: it fetches EVERY
   TicketMessage row (full `body` text included) for all 40 tickets via a
   single `ticketId IN (...)` query, orders it, and only then discards all
   but the newest per ticket. For a long-running ticket thread that is a lot
   of wasted body bytes pulled over the wire and thrown away. Instead: get
   just the max(createdAt) per ticket (a cheap aggregate, no body), then
   fetch exactly those rows — at most one per ticket. */
const ticketIds = tickets.map((t) => t.id);
const lastMessageMeta = ticketIds.length
  ? await db.ticketMessage.groupBy({
      by: ["ticketId"],
      where: { ticketId: { in: ticketIds } },
      _max: { createdAt: true },
    })
  : [];
const lastMessages = lastMessageMeta.length
  ? await db.ticketMessage.findMany({
      where: {
        OR: lastMessageMeta
          .filter((m) => m._max.createdAt)
          .map((m) => ({ ticketId: m.ticketId, createdAt: m._max.createdAt! })),
      },
      select: { ticketId: true, body: true, isStaff: true, createdAt: true },
    })
  : [];
const lastMessageByTicket = new Map(lastMessages.map((m) => [m.ticketId, m]));

const rows = tickets.map((t) => {
  const last = lastMessageByTicket.get(t.id);
  return {
    id: t.id,
    subject: t.subject,
    status: t.status,
    priority: t.priority,
    updated: t.updatedAt.toISOString(),
    /* The last message, trimmed for the list. Staff or customer is marked so a
       reader can tell at a glance whose move it is. */
    preview: last?.body.replace(/\s+/g, " ").slice(0, 120) ?? "",
    lastFromStaff: last?.isStaff ?? false,
  };
});

