cat > ./scratchpad-imgcheck.mjs <<'EOF'
import fs from "fs";
import path from "path";

const gamesTs = fs.readFileSync("./lib/games.ts", "utf8");

// crude extraction of GAME_ART_SLUG block
const start = gamesTs.indexOf("export const GAME_ART_SLUG");
const end = gamesTs.indexOf("\n};", start) + 3;
const block = gamesTs.slice(start, end);

const entryRe = /^\s*(\w+):\s*\{([^}]*)\}/gm;
let m;
const entries = {};
while ((m = entryRe.exec(block))) {
  const key = m[1];
  const body = m[2];
  const posterM = body.match(/poster:\s*"([^"]+)"/);
  const heroM = body.match(/hero:\s*"([^"]+)"/);
  entries[key] = { poster: posterM ? posterM[1] : null, hero: heroM ? heroM[1] : null };
}

const artDir = "./public/games/art";
const files = new Set(fs.readdirSync(artDir));

const rows = [];
for (const [family, {poster, hero}] of Object.entries(entries)) {
  const heroFile = hero ? `${hero}_hero.jpg` : null;
  const posterFile = poster ? `${poster}_poster.jpg` : null;
  const heroExists = heroFile ? files.has(heroFile) : false;
  const posterExists = posterFile ? files.has(posterFile) : false;
  rows.push({ family, hero, heroFile, heroExists, poster, posterFile, posterExists });
}

console.log("Total families in GAME_ART_SLUG:", rows.length);
console.log("\n-- Missing HERO file --");
rows.filter(r => !r.heroExists).forEach(r => console.log(r.family, "->", r.heroFile));
console.log("\n-- Missing POSTER (no poster key at all, or file missing) --");
rows.filter(r => !r.poster || !r.posterExists).forEach(r => console.log(r.family, "-> poster key:", r.poster, "exists:", r.posterExists));
EOF
npx tsx ./scratchpad-imgcheck.mjs

